<?php
namespace App\Models\Courses;
use App\Enums\Courses\CourseEnrollmentState;use App\Enums\Courses\FinalResult;use App\Enums\Courses\PaymentStatus;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
class CourseEnrollment extends CourseModel{protected $fillable=['course_edition_id','course_participant_id','course_enrollment_group_id','state','payment_status','activity_price_amount','certificate_charge_amount','discount_amount','subtotal_amount','currency','participation_confirmed_at','exact_average','display_average','rounded_result','final_result','result_calculated_at'];protected function casts():array{return ['state'=>CourseEnrollmentState::class,'payment_status'=>PaymentStatus::class,'activity_price_amount'=>'decimal:2','certificate_charge_amount'=>'decimal:2','discount_amount'=>'decimal:2','subtotal_amount'=>'decimal:2','participation_confirmed_at'=>'datetime','exact_average'=>'decimal:4','display_average'=>'decimal:2','rounded_result'=>'integer','final_result'=>FinalResult::class,'result_calculated_at'=>'datetime'];}public function edition():BelongsTo{return $this->belongsTo(CourseEdition::class,'course_edition_id');}public function participant():BelongsTo{return $this->belongsTo(CourseParticipant::class,'course_participant_id');}public function group():BelongsTo{return $this->belongsTo(CourseEnrollmentGroup::class,'course_enrollment_group_id');}public function attendances():HasMany{return $this->hasMany(CourseAttendance::class);}public function grades():HasMany{return $this->hasMany(CourseGrade::class);}public function academicDocuments():HasMany{return $this->hasMany(CourseAcademicDocument::class);}}
